def cout_total(lignes):
    total = 0
    for ligne in lignes:
        total = total + ligne["prix"] * ligne["nombre"]
    return total

def budget_manquant(total, budget):
    if total > budget:
        return total - budget
    return 0

def cout_avec_frais(lignes, frais):
    total = frais
    for ligne in lignes:
        total = total + ligne["prix"] * ligne["nombre"]
    return total
